impl Solution {
    pub fn min_operations(nums: Vec<i32>) -> i32 {
        let mut ops = 0;
        let mut prev = nums[0];
        for i in 1..nums.len() {
            if nums[i] <= prev {
                let diff = prev - nums[i] + 1;
                ops += diff;
                prev = nums[i] + diff;
            } else {
                prev = nums[i];
            }
        }
        ops
    }
}

